import logoAssetsJson from '../data/logo-assets.json' with { type: 'json' }

/**
 * Ink tone of a transparent logo: `light` ink vanishes on light surfaces, `dark` ink
 * on dark ones. Absent when the logo reads fine on both.
 */
export type LogoTone = 'light' | 'dark'

export type LogoAssetInfo = {
  /** A real vector exists at `/logos/<slug>.svg`. */
  svg?: true
  /** A 64px list thumbnail exists at `/thumbs/<slug>.webp`. */
  thumb?: true
  tone?: LogoTone
  thumbTone?: LogoTone
}

/** Generated by `scripts/generate-logo-assets.mts` from public/logos and data/isotipos. */
const assetsBySlug = logoAssetsJson.items as Record<string, LogoAssetInfo>

export function getLogoAssetInfo(slug: string): LogoAssetInfo {
  return assetsBySlug[slug] ?? {}
}

export function hasHostedLogoSvg(slug: string): boolean {
  return assetsBySlug[slug]?.svg === true
}

export function logoThumbPath(slug: string): string | null {
  return assetsBySlug[slug]?.thumb ? `/thumbs/${slug}.webp` : null
}

/** CSS class that gives a toned logo a contrasting tile (see globals.css). */
export function logoToneClassName(tone: LogoTone | undefined): string {
  if (tone === 'light') return 'logo-ink-light'
  if (tone === 'dark') return 'logo-ink-dark'
  return ''
}
